import React, {Component} from 'react';
import Popup from "./Popup";
import {ApiMail} from "../../api";


const sendMail = async (userMail) => {
    try {
        await ApiMail(userMail);
    } catch (e) {
        throw e;
    }
};


class PopupLogin extends Component{
    constructor(props) {
        super(props);
        this.state = {email: null, children: props};
        this.handleChange = this.handleChange.bind(this);
        this.handleSubmit = this.handleSubmit.bind(this);
    }

    handleChange(event){
        this.setState({mail: event.target.value});
    }
    handleSubmit(event) {
        console.log(this.state.email);

    }



    render() {
        return (
            <Popup>
                <div className={'form-content'}>
                    {this.state.children}
                    <p>Il sito è in fase di manutenzione e questa funzione non è al momento disponibile.</p>
                    <p>Ti chiediamo di lasciarci la mail in modo da poterti avvisare quando è pronto</p>
                    <input
                        className={"form-input"}
                        placeholder="Mail"
                        onChange={this.handleChange}
                        required
                        value={this.state.email}
                    />
                    <div className={'form-buttons'}>
                        <button className={'send-button'} onClick={sendMail}>Invia</button>
                    </div>
                </div>
            </Popup>
        )
    }

}

export default PopupLogin;
